                          unsigned long action, void *data)
{
  unsigned long val;

  if (block == &g_rptun_reboot_nb)
    {
      if (action == SYS_POWER_OFF)
        {
          val = BOARDIOC_SOFTRESETCAUSE_POWEROFF;
        }
      else if (action == SYS_HALT)
