  else if (action == PANIC_KERNEL_FINAL)
    {
      rptun_ioctl_foreach(NULL, RPTUNIOC_RESET,
                          (unsigned long)BOARDIOC_SOFTRESETCAUSE_PANIC);
    }
#endif

  return 0;
}
